class Solution:
    def maximumBinaryString(self, s: str) -> str:
        if '0' not in s:
            return s
        first_zero = s.find('0')
        zeros = s.count('0')
        ones_before = first_zero
        ones_between = zeros - 1
        ones_after = len(s) - ones_before - zeros
        return '1' * (ones_before + ones_between) + '0' + '1' * ones_after

#include <string>
#include <algorithm>
using namespace std;

class Solution {
public:
    string maximumBinaryString(string s) {
        int n = s.size();
        int first_zero = -1;
        int zeros = 0;
        for (int i = 0; i < n; ++i) {
            if (s[i] == '0') {
                if (first_zero == -1) first_zero = i;
                zeros++;
            }
        }
        if (zeros <= 1) return s;
        string res(n, '1');
        res[first_zero + zeros - 1] = '0';
        return res;
    }
};

import java.util.Arrays;

class Solution {
    public String maximumBinaryString(String s) {
        int n = s.length();
        int firstZero = -1;
        int zeros = 0;
        for (int i = 0; i < n; ++i) {
            if (s.charAt(i) == '0') {
                if (firstZero == -1) firstZero = i;
                zeros++;
            }
        }
        if (zeros <= 1) return s;
        char[] res = new char[n];
        Arrays.fill(res, '1');
        res[firstZero + zeros - 1] = '0';
        return new String(res);
    }
}

/**
 * @param {string} s
 * @return {string}
 */
var maximumBinaryString = function(s) {
    const firstZero = s.indexOf('0');
    if (firstZero === -1) return s;
    let zeros = 0;
    for (let i = 0; i < s.length; ++i) {
        if (s[i] === '0') zeros++;
    }
    if (zeros <= 1) return s;
    const res = Array(s.length).fill('1');
    res[firstZero + zeros - 1] = '0';
    return res.join('');
};
